command:
sudo tee /etc/nginx/sites-available/inventory >/dev/null <<'NGINXEOF'
upstream inventory_backends {
    least_conn;
    server 10.100.104.11:8080 max_fails=2 fail_timeout=5s;
    server 10.100.104.12:8080 max_fails=2 fail_timeout=5s;
    keepalive 16;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://inventory_backends;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_connect_timeout 2s;
        proxy_read_timeout 10s;
    }
}
NGINXEOF
sudo rm -f /etc/nginx/sites-enabled/default
sudo ln -sfn /etc/nginx/sites-available/inventory /etc/nginx/sites-enabled/inventory
sudo nginx -t
sudo systemctl enable nginx
sudo systemctl reload nginx
systemctl is-enabled nginx
systemctl is-active nginx
ss -ltn | grep ':80 '

